  "Set a password": "パスワードを設定",
  "Change password": "パスワードを変更",
  "Sign in as “{0}” with it on devices where passkeys do not work. Saving signs you out everywhere else, and paired phones have to be paired again.": "パスキーが使えない端末で、このパスワードを使って「{0}」としてログインできます。保存すると、ほかのすべての端末やブラウザからログアウトされ、ペアリング済みのスマートフォンは再度ペアリングが必要になります。",
  "Confirm with passkey & save": "パスキーで確認して保存",
  "Forgot it? Confirm with your passkey instead": "忘れた場合は、パスキーで確認できます",
