  "Add a sign-in e-mail": "ログイン用メールアドレスを追加",
  "Type it at “Sign in with password” instead of your profile name. We never send anything to it; a forgotten password is still reset by your admin.": "「パスワードでログイン」で、プロフィール名の代わりに入力できます。このアドレスにメールを送ることはありません。パスワードを忘れた場合は、引き続き管理者によるリセットが必要です。",
  "E-mail address": "メールアドレス",
