  "Use at least {0} characters.": "{0}文字以上で入力してください。",
  "That password is too long.": "パスワードが長すぎます。",
  "That password is too easy to guess. Try a longer one, or a few random words strung together.": "推測されやすいパスワードです。もっと長くするか、無関係な単語をいくつか組み合わせてください。",
  "Another profile already signs in with this name.": "この名前は別のプロフィールのログインに使われています。",
  "That invite code is not valid.": "招待コードが無効です。",
