  "Your passkey could not be confirmed.": "パスキーを確認できませんでした。",
  "This password is the only way into your profile, so it cannot be removed.": "このパスワードはプロフィールにログインする唯一の方法のため、削除できません。",
  "That reset code is wrong or has expired. Ask your admin for a new one.": "リセットコードが間違っているか、有効期限が切れています。管理者に新しいコードを発行してもらってください。",
  "This account has been disabled.": "このアカウントは無効になっています。",
