  "Add this device": "この端末を追加",
  "Added {0}": "追加日：{0}",
  "Code from your other device": "別の端末に表示されたコード",
  "Confirm with a passkey": "パスキーで確認",
  "Confirmed. Now create the new passkey; your browser will ask where to keep it.": "確認できました。新しいパスキーを作成してください。ブラウザーに保存先の選択画面が表示されます。",
  "Copy link": "リンクをコピー",
  "Create a passkey on this device for the profile “{0}”. It signs you in here from now on.": "プロフィール「{0}」のパスキーをこの端末で作成します。今後はこのパスキーでログインできます。",
  "Each one signs in to this profile from the device or password manager that keeps it. Tap one to rename or remove it.": "各パスキーは、保存先の端末やパスワードマネージャーからこのプロフィールにログインするために使います。タップすると名前の変更や削除ができます。",
  "Enter the code from your other device.": "別の端末に表示されたコードを入力してください。",
  "For this device, a security key, a password manager, or your phone through the browser’s own QR code. First confirm that it is you.": "この端末、セキュリティキー、パスワードマネージャー、またはブラウザーが表示するQRコード経由でスマートフォンに保存できます。まず本人確認を行ってください。",
  "It can no longer sign in to this profile. A device already signed in with it stays signed in. If it was lost, use Sign out everywhere.": "このパスキーでは、このプロフィールにログインできなくなります。すでにログイン済みの端末はログインしたままです。紛失した場合は「すべての端末からログアウト」を使ってください。",
  "It is your only way in, so it cannot be removed until there is another.": "唯一のログイン方法のため、別の方法を追加するまで削除できません。",
  "Last used {0}": "最終使用：{0}",
  "Make a new code": "新しいコードを発行",
  "Name, e.g. Work laptop": "名前（例：仕事用ノートパソコン）",
  "None yet. Add one and sign in without your password.": "まだありません。追加すると、パスワードなしでログインできます。",
  "Passkey added": "パスキーを追加しました",
