  "Passkey {0}": "パスキー{0}",
  "Passkeys": "パスキー",
  "Remove passkey": "パスキーを削除",
  "Remove this passkey?": "このパスキーを削除しますか？",
  "Scan this with the other device, or open openGym there and enter the code on the sign-in screen. It works once, for {0} minutes.": "別の端末でこれを読み取るか、その端末でopenGymを開き、ログイン画面にコードを入力してください。{0}分以内に1回だけ使えます。",
  "That code is wrong, already used or expired. Make a new one on your other device.": "コードが間違っているか、使用済み、または有効期限が切れています。別の端末で新しいコードを発行してください。",
  "This browser cannot confirm with your passkey. Do this on a device that holds one.": "このブラウザーではパスキーで確認できません。パスキーが保存されている端末で操作してください。",
  "First confirm that it is you.": "まず本人確認を行ってください。",
  "This profile has no passkey, and this server does not take passwords, so nothing here can confirm that it is you. Ask your admin.": "このプロフィールにはパスキーがなく、このサーバーはパスワード認証に対応していないため、ここでは本人確認ができません。管理者にお問い合わせください。",
  "This browser cannot create passkeys, so it cannot be added with a code. Open the link in a browser that can.": "このブラウザーではパスキーを作成できないため、コードで追加できません。パスキーを作成できるブラウザーでリンクを開いてください。",
  "This browser is signed in as “{0}”. Adding it to “{1}” signs “{0}” out here.": "このブラウザーでは「{0}」としてログインしています。「{1}」に追加すると、このブラウザーの「{0}」はログアウトされます。",
  "This code is for a different profile that is also called “{0}”, not the one this browser is signed in as. Adding it there signs yours out here.": "このコードは、このブラウザーでログイン中のプロフィールではなく、同じ「{0}」という名前の別のプロフィール用です。そちらに追加すると、現在のプロフィールからログアウトされます。",
  "Only continue if this code comes from a device of your own. This browser is then signed in to “{0}”, and what you log here goes to that profile.": "自分の端末で発行したコードの場合のみ続けてください。このブラウザーは「{0}」にログインし、ここでの記録はそのプロフィールに保存されます。",
  "This code has expired.": "このコードは有効期限が切れています。",
  "This device already has a passkey for this profile.": "この端末には、このプロフィールのパスキーがすでにあります。",
  "This passkey already belongs to a profile.": "このパスキーはすでにプロフィールに登録されています。",
  "This profile already has as many passkeys as it can hold.": "このプロフィールのパスキー数は上限に達しています。",
  "Use a code from your other device": "別の端末のコードを使う",
  "You get a code that lets your phone or another computer create a passkey for this profile. First confirm that it is you.": "スマートフォンや別のパソコンで、このプロフィールのパスキーを作成するためのコードを発行します。まず本人確認を行ってください。",
  "or with your password": "またはパスワードで",
  "{0} passkeys": "パスキー{0}件",
