  "The end of a rest rings through silent. Music turns down for it and keeps playing.": "マナーモードでも休憩終了音が鳴ります。音楽は一時的に音量が下がり、再生は続きます。",
  "The quieter three-beep sound from before 1.3.9, instead of the louder chime.": "大きなチャイム音の代わりに、1.3.9より前の控えめな3回のビープ音を使います。",
