  "Auto-backup on changes": "変更時に自動バックアップ",
  "Saves a dated copy to Documents/openGym after finishing a workout or editing a routine, and keeps the newest {0}. Point a sync app at that folder, or copy it out by hand.": "トレーニング終了後やルーティン編集後に、日付付きのバックアップをDocuments/openGymに保存し、最新の{0}件を保持します。同期アプリでこのフォルダーを指定するか、手動で別の場所にコピーしてください。",
  "Reset everything?": "すべてリセットしますか？",
  "Reset everything": "すべてリセット",
