  "Deletes your plan, workouts, body weight, photos and videos from your profile on this server and on every signed-in device. This cannot be undone.": "このサーバーとログイン済みのすべての端末から、プロフィールのプラン、トレーニング、体重、写真、動画を削除します。この操作は取り消せません。",
  "Sync failed: the server refused the upload as too large. Your changes have not reached the server.": "同期に失敗しました。データが大きすぎるため、サーバーがアップロードを拒否しました。変更はサーバーに反映されていません。",
  "This device is out of storage: the change is not saved on it. Signed in, it still goes to the server.": "この端末の空き容量が不足しているため、変更は端末に保存されていません。ログイン中の場合は、サーバーには送信されます。",
