  "Top of the rep range in every set. {0} {1} less help, back to {2} reps.": "全セットで上限回数を達成しました。補助を{0} {1}減らし、{2}回に戻します。",
  "Missed reps. {0} {1} of help while you build back up.": "目標回数に届きませんでした。補助を{0} {1}にして、再び積み上げましょう。",
  "Stuck for {0} sessions. Back to {1} {2} of help, then build up again.": "{0}回のトレーニングで停滞しています。補助を{1} {2}に戻し、再び積み上げましょう。",
  "Missed reps {0} sessions running. Reset to {1} {2} and work back up.": "{0}回連続で目標回数に届きませんでした。{1} {2}に戻し、再び増やしていきましょう。",
  "Missed reps. Reset to {0} {1} and work back up.": "目標回数に届きませんでした。{0} {1}に戻し、再び増やしていきましょう。",
  "Missed reps last time. Same weight again ({0} of {1} to go).": "前回は目標回数に届きませんでした。今回も同じ重量です（{1}回のうち、あと{0}回）。",
