  "Week by week": "週ごとの推移",
  "Where the sets land": "セットの強度分布",
  "Most working sets belong close to failure, not at it. Half at the floor and half at the top still average out to a healthy-looking middle.": "メインセットの多くは、限界まで追い込まず、限界に近い強度で行うのが適切です。最低と最高の強度が半分ずつでも、平均は適切そうな中間の値になります。",
  "Average effort per workout": "トレーニングごとの平均強度",
  "A fuller dot means less left in the tank. The same weight at a lower {0} is progress the line alone doesn’t show.": "点の塗りつぶしが多いほど、余力が少ないことを示します。同じ重量で{0}が下がれば、それは折れ線だけでは見えない進歩です。",
  "Bodyweight": "自重",
  "No weight to enter. Just log the reps.": "重量の入力は不要です。回数だけ記録します。",
  "Ask for a weight on every set.": "セットごとに重量を入力します。",
  "For dips or pull-ups with a belt. Progression then follows the weight.": "ベルトで加重するディップスや懸垂向けです。重量を基準に負荷を増やします。",
  "For lunges, single-arm rows and the like.": "ランジやワンハンドローなどに使います。",
  "Top of the range": "回数の上限",
  "Reps climb by one whenever every set was clean. Set a ceiling to add sets instead of reps forever.": "すべてのセットを正しいフォームでこなすたびに、回数が1回増えます。上限を設定すると、回数を増やし続けずにセット数を増やせます。",
  "Reps climb to {0}, then a set is added and the reps start over. At {1} sets it asks you to add weight instead.": "回数が{0}回まで増えると、セットが1つ追加され、回数は最初に戻ります。{1}セットに達すると、重量を増やすよう提案されます。",
