  "Use on this device": "この端末で使う",
  "Local keeps everything on this phone. Connecting syncs to your own openGym server instead. You can switch later in Settings.": "ローカル利用では、すべてのデータをこのスマートフォンに保存します。サーバーに接続すると、ご自身のopenGymサーバーと同期します。後から設定で切り替えられます。",
