  "Send": "送信",
  "Sent straight to {0} with your own API key. You pay for every request.": "自分のAPIキーで{0}に直接送信されます。リクエストごとの料金はあなたの負担です。",
  "Sent to {0}, running on this server under the instance owner’s account.": "このサーバーの所有者のアカウントで実行され、{0}に送信されます。",
  "Session length": "1回のトレーニング時間",
