  "{0} minutes is long. Rest periods may be creeping up.": "{0}分は長めです。休憩が少しずつ延びているかもしれません。",
  "Top sets logged without an effort rating; add RIR so the next review can read how hard they were.": "高重量セットにきつさの評価がありません。次回の振り返りで負荷の程度がわかるよう、RIRを追加しましょう。",
  "Add the next load step on the main lift.": "メイン種目の重量を1段階上げましょう。",
