  "Convert to {0}?": "{0}に変更しますか？",
  "Every stored weight (logged sets, working weights, routine targets, body weight, bar weights) is in {0}. Convert the numbers, or keep them and only change the label?": "保存済みの重量と体重（記録したセット、使用重量、ルーティンの目標重量、体重、バーの重量）はすべて{0}単位です。数値を換算しますか？それとも数値はそのままで単位の表示だけを変えますか？",
