  "Add this device's workouts to your profile?": "この端末のトレーニング記録をプロフィールに追加しますか？",
  "{0} workouts and {1} weigh-ins were logged on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.": "ログアウト中に、この端末でトレーニング{0}件と体重測定{1}件が記録されました。プロフィールに追加するか、サーバー上のプロフィールをそのまま使うか選んでください。",
  "{0} workout and {1} weigh-in were logged on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.": "ログアウト中に、この端末でトレーニング{0}件と体重測定{1}件が記録されました。プロフィールに追加するか、サーバー上のプロフィールをそのまま使うか選んでください。",
  "{0} workout and {1} weigh-ins were logged on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.": "ログアウト中に、この端末でトレーニング{0}件と体重測定{1}件が記録されました。プロフィールに追加するか、サーバー上のプロフィールをそのまま使うか選んでください。",
  "{0} workouts and {1} weigh-in were logged on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.": "ログアウト中に、この端末でトレーニング{0}件と体重測定{1}件が記録されました。プロフィールに追加するか、サーバー上のプロフィールをそのまま使うか選んでください。",
  "Add them": "追加する",
  "Keep profile as is": "プロフィールを変更しない",
  "Offline. Your changes are saved on this device and sync when you’re back online.": "オフラインです。変更はこの端末に保存され、オンラインに戻ると同期されます。",
  "Offline. Showing the last copy synced with the server.": "オフラインです。最後にサーバーと同期したデータを表示しています。",
