  "Off: the bar at the top is hidden. A dot on Home still warns when syncing is stuck.": "オフにすると上部のバーを非表示にします。同期が進まない場合は、引き続きホームの点でお知らせします。",
  "Connection problem": "接続の問題",
  "Backup folder": "バックアップフォルダー",
  "Chosen folder": "選択したフォルダー",
  "Use default folder": "既定のフォルダーを使う",
  "This folder can’t be used for backups.": "このフォルダーはバックアップに使えません。",
  "openGym can no longer write to “{0}”, so copies go to Documents/openGym again. Choose the folder again to switch back.": "openGymが「{0}」に書き込めなくなったため、コピーの保存先をDocuments/openGymに戻しました。元に戻すには、フォルダーを選び直してください。",
  "openGym can no longer write to the chosen folder, so copies go to Documents/openGym again. Choose the folder again to switch back.": "選択したフォルダーに書き込めなくなったため、コピーの保存先をDocuments/openGymに戻しました。元に戻すには、フォルダーを選び直してください。",
  "Nudge me when I skip a planned workout": "予定したトレーニングを休んだら通知する",
  "Nudge tone": "通知の口調",
  "Friendly": "やさしく",
  "Guilt trip": "罪悪感をくすぐる",
  "Drill sergeant": "鬼教官",
  "One nudge in the evening of a planned day with nothing logged, between 20:00 and 21:30. After 3 missed days in a row it goes quiet until your next workout.": "予定日に記録がなければ、20:00〜21:30の間に1回通知します。予定日を3回連続で休むと、次のトレーニングまで通知を止めます。",
  "Logged a workout on another device? Before the nudge goes out, the phone checks with your server whenever it lets the app run in the background. Opening the app always catches up.": "別の端末でトレーニングを記録しましたか？通知前に、スマートフォンがアプリのバックグラウンド動作を許可したタイミングでサーバーを確認します。アプリを開けば必ず最新の状態になります。",
  "Everything okay?": "大丈夫？",
  "{0} is still waiting. What’s up?": "{0}がまだ待ってるよ。どうしたの？",
  "No {0} today? Even a short session tomorrow counts.": "今日は{0}お休み？明日は短いトレーニングでも十分だよ。",
  "Rough day? {0} will keep. Tomorrow is a fresh start.": "大変な一日だった？{0}は逃げないよ。明日また始めよう。",
  "Hey, {0} didn’t happen today. All good?": "今日は{0}できなかったね。大丈夫？",
  "I miss you": "会えなくて寂しい",
  "{0} waited by the door all evening. For you.": "{0}は夕方からずっと玄関で待ってたよ。あなたのことを。",
  "The barbell asked about you today. I didn’t know what to say.": "今日、バーベルがあなたのことを聞いてきたよ。何て答えればよかったんだろう。",
  "Was it something I said? {0} misses you.": "何か気に障ること言ったかな？{0}が寂しがってるよ。",
  "I saved you a spot on the bench. It’s still empty.": "ベンチ、あなたのために空けておいたよ。まだ空いてる。",
  "Attention, recruit!": "新兵、気をつけ！",
  "Your gains are packing their bags. {0} tomorrow, no excuses!": "鍛えた筋肉が荷造りを始めたぞ。明日は{0}だ、言い訳は無用！",
  "{0} doesn’t do itself, recruit. Move it!": "新兵、{0}は勝手には終わらんぞ。動け！",
  "Excuses don’t lift weights. Report for {0} tomorrow!": "言い訳では重量は上がらん。明日は{0}に出頭せよ！",
  "Your muscles filed a missing-person report. Show up for {0}!": "筋肉がお前の捜索願を出したぞ。{0}に来い！",
  "That address answers, but it isn’t an openGym server. Check the URL.": "このアドレスから応答がありましたが、openGymサーバーではありません。URLを確認してください。",
  "That address answers, but a login page or proxy rule replied instead of openGym. Let /api/ through to openGym unchanged. See “Phone app and CORS” in docs/SELF_HOSTING.md.": "このアドレスから応答がありましたが、openGymではなくログインページかプロキシのルールによる応答でした。/api/へのリクエストを変更せずにopenGymへ通してください。docs/SELF_HOSTING.mdの「スマートフォンアプリとCORS」を参照してください。",
  "Switch sides": "左右を交代",
  "Saves a dated copy to “{0}” after finishing a workout or editing a routine, and keeps the newest {1}.": "トレーニング終了時やルーティン編集後に、日付付きのコピーを「{0}」に保存し、最新の{1}件を残します。",
  "Saves a dated copy to the folder you chose after finishing a workout or editing a routine, and keeps the newest {0}.": "トレーニング終了時やルーティン編集後に、日付付きのコピーを選択したフォルダーに保存し、最新の{0}件を残します。",
  "Plan options": "プランのオプション",
  "Your routines in a loop": "ルーティンを順番に繰り返す",
  "Back to a fixed week?": "曜日固定に戻しますか？",
  "The loop stops. Your weekdays stay as they are, and the loop is saved for later.": "ループを停止します。曜日の設定はそのまま残り、ループも後で使えるように保存されます。",
  "Routines in a loop. Whatever is next stays next until you train it, whatever the day.": "ルーティンを順番に繰り返します。次のルーティンは、曜日に関係なく実施するまで変わりません。",
  "The same routines on the same weekdays, every week.": "毎週、同じ曜日に同じルーティンを行います。",
  "How you train": "トレーニングの組み方",
  "Want two routines on one day? Tap the day and pick both.": "1日に2つのルーティンを行うには、曜日をタップして両方選んでください。",
  "The loop": "ループ",
  "{0} of {1} done this round.": "この周回は{1}件中{0}件完了。",
  "Drag to reorder. Tap the minus to take one out.": "ドラッグで並べ替え、マイナスをタップして外します。",
  "Trained out of order? Just pick another routine on Home.": "順番を変えてトレーニングしましたか？ホームで別のルーティンを選べます。",
  "Start the loop over": "ループを最初からやり直す",
  "Start the loop": "ループを開始",
  "Also on fixed days": "曜日固定の予定も追加",
  "These count on top of the loop. Tap a day to change or clear it.": "これらはループに加えて行う予定です。曜日をタップして変更や解除ができます。",
  "Now in Stats, next to Muscle balance": "「統計」の「筋肉バランス」の隣に移動しました",
