  "Each exercise can have its own rest too. Set it in the exercise settings of a routine.": "種目ごとに休憩時間を設定することもできます。ルーティン内の種目設定で指定してください。",
  "iPhone doesn’t let openGym vibrate. A sound or a flash does the job.": "iPhoneではopenGymの振動機能を使えません。通知音や画面の点滅をご利用ください。",
  "No account, no cloud. Back it up anytime in Data & backup.": "アカウントもクラウド保存もありません。「データとバックアップ」からいつでもバックアップできます。",
  "Effort per set is off. Turn it on in Settings → Workout to keep rating.": "セットごとのきつさの評価がオフです。評価を続けるには、設定 → トレーニングでオンにしてください。",
  "Enter the code your other device shows under Settings → Account → Add another device. This device then gets a passkey of its own.": "別の端末の「設定 → アカウント → 別の端末を追加」に表示されるコードを入力してください。この端末専用のパスキーが作成されます。",
  "Open Settings → Account → “Pair the mobile app” on the openGym site you’re already signed into, then enter its address and the code shown there.": "ログイン済みのopenGymサイトで「設定 → アカウント → モバイルアプリをペアリング」を開き、そのサイトのアドレスと表示されたコードを入力してください。",
  "Open Settings → Account → “Pair the mobile app” on your openGym site in a browser and enter the new code shown there. What this phone kept is merged into your account.": "ブラウザーでopenGymサイトの「設定 → アカウント → モバイルアプリをペアリング」を開き、表示された新しいコードを入力してください。このスマートフォンに保存されたデータはアカウントに統合されます。",
  "Change the time left": "残り時間を変更",
