  "That took a little too long. Give it another go.": "時間がかかりすぎました。もう一度お試しください。",
  "This server only takes changes made at {0}. If you opened openGym at another address, whoever runs the server can set ORIGIN and RP_ID to match it (the self-hosting guide shows how).": "このサーバーは{0}からの変更のみ受け付けます。別のアドレスでopenGymを開いた場合は、サーバー管理者がORIGINとRP_IDをそのアドレスに合わせて設定できます（手順はセルフホスティングガイドを参照）。",
  "That code didn’t work. Codes last 5 minutes and work once, so grab a fresh one.": "このコードは使えませんでした。コードの有効期限は5分で、1回限り使えます。新しいコードを取得してください。",
