  "{0} routine was made on this device while signed out. Add it to your profile, or keep the profile exactly as it is on the server.": "ログアウト中に、この端末で{0}件のルーティンが作成されました。プロフィールに追加するか、サーバー上のプロフィールをそのまま使うか選んでください。",
  "{0} routines were made on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.": "ログアウト中に、この端末で{0}件のルーティンが作成されました。プロフィールに追加するか、サーバー上のプロフィールをそのまま使うか選んでください。",
