  "Each set one step lighter than the one before. The weight above is the first set.": "セットごとに重量を一段階ずつ下げます。上の重量は最初のセットのものです。",
  "Sets open at {0}. The first set goes up when every set reaches its reps, and the rest follow it.": "各セットは{0}から始まります。全セットが目標回数に達すると、最初のセットの重量が上がり、残りのセットもそれに合わせて上がります。",
  "The first set goes up when every set reaches its reps, and the rest follow it.": "全セットが目標回数に達すると、最初のセットの重量が上がり、残りのセットもそれに合わせて上がります。",
