  "Weight means": "入力する重量の意味",
  "The weight of the one you hold. One arm, so it counts once.": "手に持つ器具1つの重量です。片腕で行うため、その重量を1つ分として計算します。",
  "The weight of one, so 20 means 20 in each hand. Volume counts both.": "器具1つの重量です。20と入力すると、左右それぞれの手に20を持つことになります。総負荷量には両方を含めます。",
  "Both together, so 40 means two 20s.": "左右の合計です。40なら片方20ずつです。",
  "Counted as you type it, the way it always was.": "これまでどおり、入力した数値で記録します。",
  "You’ve outgrown the rack: {0} {1} is your heaviest dumbbell, so the weight stays.": "手持ちで最も重いダンベル（{0} {1}）に達したので、重量は据え置きです。",
  "Dumbbells": "ダンベル",
  "The weights you own, one bell each. Progression, deloads, warm-ups and the + and − buttons of dumbbell lifts land only on these.": "手持ちのダンベルの重量を1個分で登録します。ダンベル種目の負荷アップ、負荷軽減、ウォームアップ、＋と−ボタンでは、この中の重量だけを使います。",
  "No list yet, so dumbbell lifts step by their increment as usual.": "リストが未登録なので、ダンベル種目はこれまでどおり設定した刻み幅で重量を変えます。",
