  "Allowed {0}": "{0}に許可済み",
  "Anything you type to the Coach": "コーチに入力するすべての内容",
  "Change your mind anytime under AI data sharing in the Coach menu.": "コーチメニューの「AIとのデータ共有」でいつでも変更できます。",
  "Nothing allowed yet": "まだ何も許可していません",
  "Okay, nothing was sent.": "何も送信していません。",
  "Send your training to {0}?": "トレーニング情報を{0}に送信しますか？",
  "The Coach asks before anything leaves.": "コーチはデータを外部に送信する前に必ず確認します。",
  "Through your server": "自分のサーバー経由",
  "To answer, the Coach sends this through your openGym server to {0}, an AI service outside openGym that your server’s admin picked:": "回答のため、コーチは次の情報をopenGymサーバー経由で{0}に送信します。このサービスはサーバー管理者が選択したopenGym外部のAIサービスです：",
  "To answer, this device sends this straight to {0}, an AI service outside openGym, with your API key:": "回答を得るために、あなたのAPIキーを使い、この端末からopenGym外部のAIサービス{0}へ以下を直接送信します：",
  "Who may see your training": "トレーニング情報の共有先",
  "Who the Coach may send your training to from this device. Withdraw it and the Coach asks again next time. A model on your own network never needs asking.": "コーチがこの端末からトレーニング情報を送信できる相手です。許可を取り消すと、次回は再び確認します。自分のネットワーク内のモデルには確認不要です。",
  "With your API key": "自分のAPIキーを使用",
  "Withdraw": "許可を取り消す",
  "Withdrawn. The Coach will ask before it sends anything again.": "許可を取り消しました。コーチは次にデータを送信する前に再び確認します。",
  "Your answers to the Coach: goal, days, equipment, limits and injuries": "コーチへの回答：目標、日数、器具、制限事項、けが",
  "Your body weight and goal weight": "体重と目標体重",
  "Your data, your call": "データの共有はあなたが決めます",
  "Your name, email and sign-in stay put. {0} handles the rest under its own privacy terms.": "名前、メールアドレス、ログイン情報は送信しません。それ以外の情報は、{0}が独自のプライバシー規約に従って扱います。",
  "Your plan: routines, exercises, sets, reps and schedule": "トレーニング計画：ルーティン、種目、セット数、回数、スケジュール",
  "Your unit and language": "使用する単位と言語",
  "Your workouts: weights, reps, times, effort and session notes": "トレーニング記録：重量、回数、時間、きつさ、トレーニングのメモ",
  "Delete my account": "自分のアカウントを削除",
  "Removes your profile and everything in it from this server.": "このサーバーからプロフィールとその中のすべてのデータを削除します。",
  "Delete your account?": "アカウントを削除しますか？",
  "Your profile, workouts, body weight, photos and videos are deleted from this server for good. There is no undo, and not even your admin can bring them back.": "プロフィール、トレーニング、体重、写真、動画をこのサーバーから完全に削除します。取り消しはできず、管理者でも復元できません。",
  "Want a copy first? Export a backup. You can import it into openGym anytime.": "データを残したい場合は、先にバックアップを書き出してください。いつでもopenGymに読み込めます。",
  "Type {0} to confirm.": "確認のため「{0}」と入力してください。",
  "Account name": "アカウント名",
  "Delete forever": "完全に削除",
  "That is not your account name.": "アカウント名が一致しません。",
  "You’re the only admin here, and other profiles still use this server. Make someone else an admin first.": "あなたは唯一の管理者で、他のプロフィールもこのサーバーを使用しています。先に別の人を管理者にしてください。",
  "Couldn’t delete the account. Nothing was removed.": "アカウントを削除できませんでした。何も削除されていません。",
  "Your account is gone. Thanks for every rep.": "アカウントを削除しました。これまでのトレーニング、お疲れさまでした。",
  "Confirm it’s you to delete your openGym account": "openGymアカウントを削除するために本人確認をしてください",
  "Not confirmed on this phone. Nothing was deleted.": "このスマートフォンで本人確認ができませんでした。何も削除されていません。",
  "This phone has no screen lock, so the name you typed is the only check.": "このスマートフォンには画面ロックがないため、入力した名前だけで確認します。",
  "Your phone checks that it’s you (face, fingerprint or passcode), then the account is deleted.": "スマートフォンで本人確認（顔・指紋・パスコード）を行ってから、アカウントを削除します。",
  "Never miss the end of a rest": "休憩の終了を見逃さない",
  "One quick thing": "ひとつだけ確認",
  "Rest timer, right on the lock screen": "ロック画面に休憩タイマーを表示",
