  "You can change it anytime in your phone’s settings.": "スマートフォンの設定でいつでも変更できます。",
  "openGym can tap you on the shoulder when a rest is over, even with the phone locked in your pocket.": "スマートフォンをロックしてポケットに入れていても、openGymが休憩の終了をお知らせします。",
  "A good size for this screen.": "この画面に適したサイズです。",
