  "Your bars": "使用するバー",
  "Set the bar once for every exercise of a type.": "種類ごとにバーを設定すると、同じ種類の全種目に適用されます。",
  "Your bar for this type, set in Your bars.": "「使用するバー」で設定した、この種類のバーです。",
  "What the bars at your gym weigh. Every exercise with that bar counts plates from it, unless you gave the exercise its own. Logged weights stay totals.": "ジムのバーの重量を設定します。そのバーを使う全種目で、この重量をもとにプレートを計算します。種目ごとに重量を設定した場合は、そちらを使います。記録する重量は合計重量のままです。",
  "Most lifts in the library use “{0}”, a few use “{1}”. A short bar for all of them means setting both.": "ライブラリのほとんどの種目は「{0}」、一部は「{1}」を使います。すべて短いバーで行う場合は、両方を設定してください。",
  "Back to the standard bars": "標準のバーに戻す",
  "Standard bars. Tap if yours are lighter.": "標準のバーです。使っているバーが軽い場合はタップしてください。",
  "The last warm-up still gets the full rest before your first work set.": "最後のウォームアップ後も、最初の本番セットまで、設定した時間いっぱい休憩します。",
