  "Not trained:": "鍛えていない部位：",
  "Rounded to whole sets. A set counts fully for its main muscle and partly for the ones that help, so the muscles add up to more than your work sets.": "セット数は整数に丸めています。1セットは主に使う筋肉に1セット分、補助する筋肉にも一部を加算するため、筋肉別の合計は本番セット数を上回ります。",
