  "The schedule in your plan right now becomes this programme’s.": "現在のプランのスケジュールを、このプログラムに使います。",
  "The week is the calendar week: week 1 is the one you start in. A pause holds it.": "週はカレンダーに合わせて数え、開始した週が第1週になります。一時停止中は週が進みません。",
  "This programme is gone.": "このプログラムは削除されています。",
  "Three days of plain linear progression, with a deload every fourth week.": "週3日、シンプルに負荷を上げていき、4週ごとに負荷を下げます。",
  "Three days on the 5×5 routines, a little heavier every week, then a light week to bounce back.": "週3日の5×5ルーティンで毎週少しずつ重量を増やし、最後は負荷を軽くして回復する週を設けます。",
  "Upper / lower by effort, 6 weeks": "運動強度に合わせた上半身・下半身分割・6週間",
