  "Finish saves the session and moves your weights along. This practice one just quietly disappears.": "「終了」でトレーニングを保存し、次回の重量を更新します。この練習用のトレーニングは保存されずに消えます。",
  "Finish the tour?": "ガイドを終了しますか？",
  "Finish your workout first, then the tour is all yours.": "トレーニングを終了すると、ガイドを見られます。",
