  "Let’s go": "始めましょう",
  "Make it yours": "自分好みに",
  "Muscles at a glance": "筋肉の状態をひと目で",
  "Narrow the list by body part, type or the equipment you have.": "部位や種類、使える器具で一覧を絞り込めます。",
  "No thanks": "今はしない",
  "Pick an exercise to see its best sets, estimated max and where it’s heading.": "種目を選ぶと、ベストセット、推定最大重量、記録の推移を確認できます。",
  "Pointing at: {0}": "案内中：{0}",
  "Practice run": "練習",
  "Programmes and sharing": "プログラムと共有",
  "Programmes, starter plans and sharing a plan with a friend live behind this button.": "このボタンから、プログラムや入門プランを開いたり、友達にプランを共有したりできます。",
  "Records": "記録",
  "Schedule says when, Routines says what. Build your own or grab a starter plan.": "「スケジュール」で実施日を、「ルーティン」で内容を決めます。自分で作ることも、入門プランを使うこともできます。",
  "Search thousands of exercises in your language. Star your favourites and they float to the top.": "数千の種目をお使いの言語で検索できます。お気に入りに星を付けると、一覧の上に表示されます。",
  "See which muscles got the work and which still need rest. Tap one for details.": "鍛えた筋肉や、まだ休憩が必要な筋肉を確認できます。タップすると詳細が表示されます。",
  "Show me": "見てみる",
  "Show the tour again": "ガイドをもう一度見る",
  "Skip tour": "ガイドをスキップ",
  "Step {0} of {1}": "ステップ{0}／{1}",
  "Swipe a set": "セットをスワイプ",
  "Swipe a set sideways to copy or remove it. Its number opens even more.": "セットを横にスワイプすると、コピーや削除ができます。セット番号をタップすると、ほかの操作も表示されます。",
  "The big Start button": "大きな「開始」ボタン",
  "The little body shows what each day works, so leg day can’t hide.": "小さな人体図で、その日に鍛える部位がわかります。脚の日も見逃しません。",
  "The rest timer starts by itself. Add time, or skip it if you feel heroic.": "休憩タイマーは自動で始まります。時間を延ばしたり、元気があればスキップしたりできます。",
  "The ⋯ menu": "「⋯」メニュー",
  "Theme, accent colour and what Home shows.": "テーマ、アクセントカラー、ホームの表示内容を設定できます。",
  "This one is pretend, nothing gets saved. Each row is a set: weight, then reps. Tap a number to change it.": "これは練習用なので、何も保存されません。各行が1セットで、重量、回数の順に並んでいます。数字をタップすると変更できます。",
  "Tick it off": "完了をチェック",
  "Today at a glance": "今日の予定をひと目で",
  "Today’s session lives here. One tap and you’re lifting. On a rest day it says so, no guilt trip.": "今日のトレーニングはここに表示され、ワンタップで始められます。休養日はそう表示されるので、気兼ねなく休めます。",
  "Train on fixed weekdays, or run your routines in a loop where the next one waits for you.": "決まった曜日に行うか、次のルーティンが待っていてくれるローテーションで進めるかを選べます。",
  "Want a 1-minute tour?": "1分間のガイドを見ますか？",
  "Week or rotation": "曜日固定かローテーション",
  "We’ll point at the good bits on the real screens. Bail out anytime.": "実際の画面で便利な機能をご案内します。いつでも終了できます。",
  "Workout settings, layouts, notes and extra exercises hide in here.": "トレーニングの設定、レイアウト、メモ、種目の追加はここにあります。",
  "Workouts, streaks and everything you’ve lifted. It fills up as you train.": "トレーニング、連続記録、これまで挙げた重量。続けるほど記録が増えていきます。",
  "You stopped halfway. Want to see the rest?": "ガイドが途中でした。続きを見ますか？",
  "Your data, your backups": "自分のデータとバックアップ",
  "Your progress": "成長の記録",
  "Your routines": "自分のルーティン",
  "You’re set": "準備完了",
  "Previous year": "前年",
  "Next year": "翌年",
  "Pick a month": "月を選択",
  "Pick a day": "日を選択",
  "With pictures": "画像付き",
  "A small picture next to each exercise, like a plan from the gym.": "ジムのメニュー表のように、各種目の横に小さな画像を表示します。",
  "This one lives in the openGym phone app: Apple Health on iPhone, Health Connect on Android.": "この機能はスマートフォン版openGymで使えます。iPhoneではAppleヘルスケア、Androidではヘルスコネクトと連携します。",
  "Webhooks are sent by your own openGym server, so they need one. Connect this device to it in Account.": "ウェブフックは自分のopenGymサーバーから送信するため、サーバーが必要です。「アカウント」でこの端末を接続してください。",
  "Webhooks are off on this server. Add INTEGRATIONS=webhook to its .env and restart it.": "このサーバーではウェブフックが無効です。.envにINTEGRATIONS=webhookを追加し、サーバーを再起動してください。",
  "The MCP server runs next to your own openGym server and reads your data there.": "MCPサーバーは自分のopenGymサーバーと併せて動作し、そこにあるデータを読み取ります。",
  "Only what you switch on talks to anything. The rest stays out of your way.": "有効にした機能だけが外部と通信します。それ以外は動作しません。",
  "Could not reach your server": "サーバーに接続できませんでした",
  "Tap to try again": "タップして再試行",
  "Disconnect {0}?": "{0}との連携を解除しますか？",
  "openGym stops writing and reading. What it already wrote can stay there as your data, or go.": "openGymによる読み書きを停止します。書き込み済みのデータは、そのまま残すか削除するかを選べます。",
  "Works with": "対応サービス",
  "No extra connection needed: they write to {0}, and openGym reads from there.": "追加の連携は不要です。各サービスが{0}に書き込んだデータを、openGymが読み取ります。",
  "No extra connection needed: they write to Apple Health or Health Connect, and the openGym phone app reads from there.": "追加の連携は不要です。各サービスがAppleヘルスケアやヘルスコネクトに書き込んだデータを、スマートフォン版openGymが読み取ります。",
  "{0} has no direct line to openGym, and it does not need one.": "{0}とopenGymの直接連携はありませんが、必要もありません。",
  "How it gets here": "データが届く仕組み",
  "{0} saves to Apple Health on iPhone or Health Connect on Android. openGym reads from there.": "{0}はiPhoneではAppleヘルスケア、Androidではヘルスコネクトにデータを保存します。openGymはそこから読み取ります。",
  "What openGym reads": "openGymが読み取るデータ",
  "What it does not do": "行わないこと",
  "Workouts logged in openGym go to the health store, not back into {0} itself.": "openGymで記録したトレーニングはヘルスケアデータの保存先に送られ、{0}自体には送られません。",
  "Set up {0}": "{0}を設定",
  "Install the openGym app on your phone to use this.": "この機能を使うには、スマートフォンにopenGymアプリをインストールしてください。",
