  "Retry": "再試行",
  "Webhooks": "ウェブフック",
  "Your server sends a signed message to each of these when something happens.": "イベントが発生すると、サーバーが各送信先に署名付きメッセージを送ります。",
  "Add a webhook": "ウェブフックを追加",
  "What gets sent": "送信する内容",
  "Pick at least one thing to send.": "送信する項目を1つ以上選んでください。",
  "Your server said no to that URL: {0}": "サーバーがこのURLへの送信を拒否しました：{0}",
  "it is not one it calls.": "許可された送信先ではありません。",
  "Webhook added": "ウェブフックを追加しました",
  "This is its signing secret. You will see it only now, so paste it into your tool if it checks signatures.": "これが署名用の秘密鍵です。表示されるのは今回だけです。連携先のツールで署名を検証する場合は、そこに貼り付けてください。",
  "Signing secret": "署名用の秘密鍵",
  "Copy secret": "秘密鍵をコピー",
  "Paste the URL from Home Assistant, n8n, ntfy or similar. Your home network works too.": "Home Assistant、n8n、ntfyなどのURLを貼り付けてください。自宅のネットワーク内のURLも使えます。",
  "Paste the HTTPS URL from Home Assistant, n8n, ntfy or similar.": "Home Assistant、n8n、ntfyなどのHTTPSのURLを貼り付けてください。",
