  "AI & API": "AIとAPI",
  "Workouts and weigh-ins out, heart rate and scale readings in.": "トレーニングと体重の記録を送信し、心拍数と体重計の測定値を取り込みます。",
  "Finished workouts and weigh-ins go to Apple Health.": "完了したトレーニングと体重の記録をAppleヘルスケアに送信します。",
  "Heart rate from your watch fills in each set.": "ウォッチで測定した心拍数を各セットに記録します。",
  "Weigh-ins from your smart scale land here.": "スマート体重計で測った体重をここに取り込みます。",
  "Finished workouts and weigh-ins go to Health Connect.": "完了したトレーニングと体重の記録をヘルスコネクトに送信します。",
