  "Workouts, routines and weigh-ins, once.": "トレーニング、ルーティン、体重の記録を一度だけ取り込みます。",
  "The key is used for this import and then forgotten.": "キーは今回のインポートにのみ使用し、保存しません。",
  "Import a file": "ファイルをインポート",
  "Strong, FitNotes, Hevy CSV, GymMane or an Apple Health export.": "Strong、FitNotes、HevyのCSV、GymMane、またはAppleヘルスケアのエクスポートファイル。",
  "Reads the export file of another app, once.": "他のアプリのエクスポートファイルを一度だけ読み込みます。",
  "Exercises are matched to the library, you check the rest.": "種目をライブラリと照合します。残りは自分で確認してください。",
  "Spreadsheet (CSV)": "スプレッドシート（CSV）",
  "Every set, weigh-in and measurement, for Excel and friends.": "すべてのセット、体重、身体のサイズの記録をExcelなどで使える形式に。",
  "One row per set, plus body weight and measurements.": "セットごとに1行で出力し、体重や身体のサイズの記録も含めます。",
  "openGym can read it back in later.": "後からopenGymに再び取り込めます。",
  "Tell Home Assistant, n8n or ntfy when you finish a workout.": "トレーニング完了時にHome Assistant、n8n、ntfyに通知します。",
  "A signed JSON message when a workout is finished, a record falls or you weigh in.": "トレーニングの完了、自己ベストの更新、体重の記録時に署名付きJSONメッセージを送信します。",
  "Sent by your server, from whichever device you logged on.": "どのデバイスで記録しても、自分のサーバーから送信されます。",
  "Plans and reviews from the model you pick.": "選んだモデルがプラン作成や振り返りをサポートします。",
  "Reads your plan and the last weeks of training when you ask.": "依頼したときに、プランと直近数週間のトレーニングを読み取ります。",
  "Set up on its own page.": "専用ページで設定します。",
  "MCP server": "MCPサーバー",
  "Let Claude Desktop, Cursor and friends read your training log.": "Claude DesktopやCursorなどからトレーニング記録を読み取れるようにします。",
  "Runs next to your server and reads your data from there.": "サーバーと併せて動作し、そこからデータを読み取ります。",
  "Read-only, apart from logging a workout you ask it to.": "依頼したトレーニングの記録以外は、読み取り専用です。",
