  "Oura": "Oura",
  "Withings": "Withings",
  "Renpho": "Renpho",
  "A new routine": "新しいルーティン",
  "A photo or video": "写真や動画",
  "Add an exercise first, then it’s worth saving.": "まず種目を追加してから保存しましょう。",
  "Add exercises": "種目を追加",
  "Add it to the loop": "繰り返しに追加",
  "An exercise’s history, records and progress are worked out from your workouts. Fix the workout and they follow.": "種目の履歴、記録、進捗はトレーニングから算出されます。トレーニングを修正すると、それらも更新されます。",
  "Back home, practice over. Stats is where the gains pile up. Tap it.": "ホームに戻って練習は終了です。成果は「統計」に集まります。タップしましょう。",
  "Back it all up": "すべてバックアップ",
  "Back to Stats": "統計に戻る",
