  "Waiting till you close that": "その画面を閉じるまで待機中",
  "Up next: {0}, starts by itself": "次は{0}。自動で始まります",
  "When the rest ends: 3, 2, 1 and the hold starts. Pause, restart or stop it any time.": "休憩が終わると、3、2、1のカウントでホールド開始。いつでも一時停止、やり直し、終了できます。",
  "Holds start by themselves": "ホールドが自動で始まります",
  "Add {0}?": "{0}を追加しますか？",
  "Any blank NTAG sticker works. Writing replaces what was on it.": "空のNTAGステッカーならどれでも使えます。書き込むと元の内容は上書きされます。",
  "Hold the back of your phone to the sticker.": "スマートフォンの背面をステッカーにかざしてください。",
  "Hold the top of your iPhone near the sticker.": "iPhoneの上部をステッカーに近づけてください。",
  "It isn’t in this workout yet.": "このトレーニングにはまだ含まれていません。",
  "Just check in": "チェックインのみ",
  "NFC is off. Turn it on in your phone’s settings and try again.": "NFCがオフです。スマートフォンの設定でオンにして、もう一度お試しください。",
  "NFC sticker for this exercise": "この種目のNFCステッカー",
  "Put it on your locker, your bag or the gym door. One tap with your phone and you’re in.": "ロッカーやバッグ、ジムのドアに貼っておけば、スマートフォンをかざすだけでチェックインできます。",
  "Set up an NFC sticker": "NFCステッカーを設定",
  "Shows your gym membership code, ready for the scanner.": "スキャナーで読み取れるジムの会員コードを表示します。",
  "Start today’s workout": "今日のトレーニングを開始",
  "Starts what’s planned for today, or opens the one already running.": "今日の予定のトレーニングを開始するか、実施中のトレーニングを開きます。",
  "Stick it on the machine. Tap it during a workout to jump to {0}, or to add it.": "マシンに貼っておきましょう。トレーニング中にかざすと、{0}に移動するか、追加できます。",
  "Sticker ready.": "ステッカーの準備ができました。",
  "Sticker ready. Tap it with your phone to try it.": "ステッカーの準備ができました。スマートフォンをかざして試してみましょう。",
  "Tap it at the gym to start your workout or show your code.": "ジムでかざすと、トレーニングの開始やコードの表示ができます。",
  "That didn’t work. Hold your phone still on the sticker and try again.": "うまくいきませんでした。スマートフォンをステッカーにかざしたまま動かさず、もう一度お試しください。",
  "This sticker can’t hold a link. Try an NTAG sticker.": "このステッカーにはリンクを書き込めません。NTAGステッカーをお試しください。",
  "This sticker is for an exercise you don’t have.": "このステッカーの種目は登録されていません。",
  "This sticker is locked. Try a blank one.": "このステッカーはロックされています。空のステッカーをお試しください。",
  "This sticker is too small. NTAG213 or bigger works.": "このステッカーは容量が足りません。NTAG213以上の容量のものをお使いください。",
  "When you tap it": "かざしたときの動作",
  "Which code": "表示するコード",
