  "Your watch thought this workout was forgotten. It keeps going here.": "ウォッチはこのトレーニングを終了し忘れたと判断しました。こちらでは継続しています。",
  "No rule (freestyle)": "ルールなし（フリースタイル）",
  "Freestyle keeps the numbers you set. A rule picked here applies to this workout only.": "フリースタイルでは設定した数値が維持されます。ここで選んだルールは、今回のトレーニングにのみ適用されます。",
  "A number of ramp sets": "段階的に重量を上げるセット数",
