  "Do {0} last": "{0}を最後に行う",
  "Do {0} next": "{0}を次に行う",
  "Each one closes half the gap to the work weight.": "セットごとに、メインセットの重量との差を半分ずつ縮めます。",
  "Every loaded lift": "重量を使うすべての種目",
  "Feeling great": "調子がいい",
  "Follows Settings → Workout → Automatic warm-ups.": "設定 → トレーニング → 自動ウォームアップの設定に従います。",
  "For this workout": "今回のトレーニングのみ",
  "Heavy lifts get more rungs, light ones one or none.": "重量が重い種目では段階を増やし、軽い種目では1段階またはなしにします。",
  "It hurts": "痛みがある",
  "It hurts, it’s taken, no time, feeling great": "痛みがある、器具が使用中、時間がない、調子がいい",
  "It pinches, so lighter for the rest of it. Stop if it still hurts.": "鋭い痛みがあるため、残りは重量を軽くします。それでも痛む場合は中止してください。",
  "It pinches, so the sets you have left go to a movement that loads the same muscle from a kinder angle.": "鋭い痛みがあるため、残りのセットは同じ筋肉をより無理のない角度で鍛える動きに変更します。",
  "Keep these warm-ups": "このウォームアップを保存",
  "Kept. Same warm-ups next time, scaled to your work weight.": "保存しました。次回も同じウォームアップを、メインセットの重量に合わせて調整します。",
  "Logged sets and your routine stay as they are. The Coach is not a doctor or a physiotherapist. If something hurts, ask a professional.": "記録済みのセットとルーティンは変更されません。コーチは医師や理学療法士ではありません。痛みがある場合は専門家に相談してください。",
  "Looking at your workout…": "トレーニングを確認中…",
  "Machine’s taken": "マシンが使用中",
  "My own": "自分で設定",
  "New programme “{0}”": "新しいプログラム「{0}」",
  "Nothing at {0} {1}: that one starts cold.": "{0} {1}ではウォームアップなしで開始します。",
  "Nothing could be applied any more.": "適用できる変更はもうありませんでした。",
  "Nothing to change. Carry on as planned.": "変更は不要です。予定どおり続けましょう。",
  "One set less keeps the session doable today and still counts.": "1セット減らせば、今日も無理なく取り組めます。それでも十分トレーニングになります。",
  "Only the warm-ups you plan yourself.": "自分で設定したウォームアップのみ行います。",
  "Ramped from the work weight: more rungs when it is heavy, fewer when it is light.": "メインセットの重量を基に段階的に重量を上げます。重ければ段階を増やし、軽ければ減らします。",
  "Remove warm-up {0}": "ウォームアップ{0}を削除",
  "Revise programme “{0}”": "プログラム「{0}」を見直す",
  "Routines, exercises, sets and reps, warm-ups, programmes, your weekly schedule, progression settings and what your gym can load.": "ルーティン、種目、セット数と回数、ウォームアップ、プログラム、週間スケジュール、負荷の増やし方の設定、ジムで使える重量。",
  "Running on empty": "力が出ない",
  "Saved in the routine, scaled to your work weight": "ルーティンに保存し、メインセットの重量に合わせて調整",
  "Saved under Plan → Programmes. It starts when you start it.": "プラン → プログラムに保存しました。開始するタイミングは自分で選べます。",
  "Short on time": "時間がない",
  "Skip the rest of {0}": "{0}の残りをスキップ",
  "Something else": "その他",
  "Squats, presses, rows and friends get a ramp. Curls and raises start cold.": "スクワット、プレス、ローなどは段階的に重量を上げます。カールやレイズはウォームアップなしで始めます。",
  "Straight into the work sets.": "すぐにメインセットへ。",
  "That workout is over, so these can’t be applied any more.": "そのトレーニングは終了したため、これらの変更はもう適用できません。",
  "The app ramps up from your work weight: more warm-up sets when it is heavy, fewer when it is light, on your gym’s plates.": "メインセットの重量を基準に、段階的に重量を上げます。重い日はウォームアップのセットを多く、軽い日は少なくし、ジムにあるプレートに合わせます。",
  "The rack is taken, so do it at the end. The rest of the session does not need it.": "ラックが使用中なので、この種目は最後に回しましょう。他の種目ではラックを使いません。",
  "There’s no workout running.": "進行中のトレーニングはありません。",
  "These warm-ups come before the work sets every session, as a share of the work weight, so they grow with it.": "毎回メインセットの前に行うウォームアップです。メインセットの重量に対する割合で設定するため、その重量に合わせて増えます。",
  "This is the demo, so there is no AI model behind me. On your own server I read your session and suggest changes like these.": "これはデモのため、AIモデルは動作していません。ご自身のサーバーでは、トレーニング内容を読み取り、このような変更を提案します。",
  "Warm-up {0}": "ウォームアップ{0}",
  "Warm-ups": "ウォームアップ",
  "What’s up? The Coach suggests a few changes to what is left of this workout. Logged sets stay as they are.": "どうしましたか？コーチがトレーニングの残りの内容に変更を提案します。記録済みのセットはそのままです。",
